def collect(base, rel):
    p=os.path.join(base,rel) if rel!='.' else base
    if not os.path.exists(p): return []
    if os.path.isfile(p): return [p]
    out=[]
    for dp,dns,fns in os.walk(p):
        dns[:]=[d for d in dns if d not in {'node_modules','.git','dist','target','__pycache__','.venv','venv'}]
        for fn in fns:
            if os.path.splitext(fn)[1].lower() in {'.vue','.js','.ts','.py','.scss','.css','.md','.json','.bat','.env','.mjs','.mdc'}:
                out.append(os.path.join(dp,fn))
    return out

def main():
    res={}
    for idx,(bases,patterns) in CHECKS.items():
        files=[]
        for b,rel in bases: files+=collect(b,rel)
        files=list(dict.fromkeys(files))
        comps=[re.compile(rx,re.I) for _,rx in patterns]
        hits={label:[] for label,_ in patterns}
        for f in files:
            try: t=open(f,encoding='utf-8',errors='ignore').read()
            except: continue
            for (label,rx),c in zip(patterns,comps):
                m=c.search(t)
                if m and len(hits[label])<4:
                    ln=t.count('\n',0,m.start())+1
                    hits[label].append(os.path.relpath(f,R)+':'+str(ln))
        res[str(idx)]={"nfiles":len(files),"hits":hits}
    open(r"C:/Users/Administrator/.dsh/cache/memory-audit/deep_result.json",'w',encoding='utf-8').write(json.dumps(res,ensure_ascii=False,indent=1))
    print('ok',len(res))
if __name__=='__main__': main()

